// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address callee, address[] memory tos, uint256 v) public {
        // admissible domain: tos must be non-empty as required by the contract
        vm.assume(tos.length > 0);
        // The contract makes low-level calls to `callee`. An EOA would simply succeed (empty code) so
        // we allow any callee address (fuzzer may provide EOAs or contracts). We do not restrict other params.

        // call transfer and capture whether it returns true (does not revert and returns true)
        bool ok;
        try c.transfer(from, callee, tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, consider that as not satisfying the property (but reference should not revert for admissible inputs)
            ok = false;
        }

        // The universal property: for any admissible input (tos.length>0), reference returns true.
        // The mutant that always returns false will make this assertion fail for some inputs (indeed for any admissible input
        // that does not revert). We assert that c.transfer(...) returned true.
        assertTrue(ok);
    }
}
